import {createCosmos} from './cosmos.4600e79cc304.js';
const changeScene=createCosmos(document.getElementById('cosmos'));
const poems=['山河为骨，星海为界。为想象找到一处栖身之地。','岁月流转，因果相续。在漫长的时间中，写下世界的来路。','万千生灵，各有其道。让每一个名字，都有自己的命运。','一物一理，生生不息。从灵气到法则，构筑世界的脉络。'];
const sceneNames=['山河初境','岁月星轨','众生因缘','万象归一'];
const $=id=>document.getElementById(id), cats=['天地','时序','众生','万物'], descriptions={'天地':'世界在哪里','时序':'世界如何演变','众生':'谁在世界中','万物':'世界如何运转'}, legacy={'世界起源':'时序','天地地理':'天地','宗门势力':'众生','风俗文化':'众生','修炼体系':'万物','天道法则':'万物','历史纪元':'时序','万物生灵':'众生','其他设定':'万物'}, key='wanxiang-v1';
let data={version:1,world:'未命名的修仙世界',entries:[]},selected=null,active='天地',blocked=false;
function validate(d){if(!d||d.version!==1||typeof d.world!=='string'||!Array.isArray(d.entries))throw Error('备份格式不正确');const ids=new Set();for(const e of d.entries){if(!e||typeof e.id!=='string'||!e.id||ids.has(e.id)||typeof e.title!=='string'||typeof e.content!=='string'||(!cats.includes(e.category)&&!Object.hasOwn(legacy,e.category))||!['构思中','待完善','已定稿'].includes(e.status)||typeof e.updated!=='string')throw Error('设定格式不正确');ids.add(e.id)}return {...d,entries:d.entries.map(e=>legacy[e.category]?{...e,previousCategory:e.category,category:legacy[e.category]}:e)}}
function notice(s){$('notice').textContent=s}
try{const raw=localStorage.getItem(key);if(raw)data=validate(JSON.parse(raw))}catch{blocked=true;notice('已有数据无法读取，自动保存已暂停以保护原数据。请检查浏览器存储。')}
function save(){if(blocked){$('saved').textContent='自动保存已暂停';return}try{localStorage.setItem(key,JSON.stringify(data));$('saved').textContent='已自动保存'}catch{$('saved').textContent='保存失败';notice('存储空间不足或不可用，请立即导出备份。')}}
let panelAnimation;
function animatePanel(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;panelAnimation?.cancel();panelAnimation=document.querySelector('.hero-copy').animate([{opacity:.45,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,easing:'cubic-bezier(.22,1,.36,1)'});}
function render(){ if(!$('nav').children.length)for(const c of cats){const b=document.createElement('button');b.className=c===active?'active':'';b.setAttribute('aria-pressed',String(c===active));const name=document.createElement('strong');name.textContent=c;const desc=document.createElement('span');desc.textContent=descriptions[c];b.append(name,desc);b.onclick=()=>{if(active===c)return;active=c;$('search').value='';open(null);animatePanel()};$('nav').append(b)}for(const [i,b] of [...$('nav').children].entries()){b.className=cats[i]===active?'active':'';b.setAttribute('aria-pressed',String(cats[i]===active));}$('nav').style.setProperty('--active-index',cats.indexOf(active));document.body.dataset.realm=cats.indexOf(active);changeScene(cats.indexOf(active));$('chapter').textContent=['第一卷','第二卷','第三卷','第四卷'][cats.indexOf(active)];$('poem').textContent=poems[cats.indexOf(active)];$('scene-name').textContent=sceneNames[cats.indexOf(active)];$('scene-number').textContent=['壹','贰','叁','肆'][cats.indexOf(active)]+' / 肆';$('hero-count').textContent=data.entries.filter(e=>e.category===active).length+' 篇设定 · 万象渐成';$('heading').textContent=active;$('description').textContent=descriptions[active];$('empty-title').textContent='为'+active+'写下第一条设定';$('empty-description').textContent='点击“新建设定”，开始记录'+descriptions[active]+'。';$('search').placeholder='搜索'+active+'中的设定…';const q=$('search').value.trim().toLowerCase(),list=data.entries.filter(e=>(!active||e.category===active)&&(e.title+'\n'+e.content).toLowerCase().includes(q)).sort((a,b)=>b.updated.localeCompare(a.updated));$('count').textContent=`设定卷宗 · ${list.length} 篇`;$('list').replaceChildren();if(!list.length){const p=document.createElement('p');p.textContent=q?'没有找到匹配的设定':'这里还没有设定，开始记录吧。';$('list').append(p)}for(const e of list){const b=document.createElement('button');b.className='entry'+(selected===e.id?' current':'');for(const [tag,text] of [['small',e.category+' · '+e.status],['strong',e.title||'未命名设定'],['p',e.content.slice(0,85)||'等待你写下这个世界的故事…']]){const n=document.createElement(tag);n.textContent=text;b.append(n)}b.onclick=()=>open(e.id);$('list').append(b)}}
function open(id){selected=id;const e=data.entries.find(e=>e.id===id);$('empty').hidden=!!e;$('form').hidden=!e;if(e){for(const f of ['title','category','status','content'])$(f).value=e[f];$('words').textContent=e.content.length+' 字';$('saved').textContent=blocked?'自动保存已暂停':'编辑后自动保存'}render()}
for(const c of cats){const o=document.createElement('option');o.textContent=c;$('category').append(o)}$('form').onsubmit=e=>e.preventDefault();
$('empty-new').onclick=()=> $('new').click();
$('new').onclick=()=>{const e={id:crypto.randomUUID(),title:'',content:'',category:active||cats[0],status:'构思中',updated:new Date().toISOString()};data.entries.push(e);$('search').value='';open(e.id);save();$('form').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});$('title').focus({preventScroll:true})};
for(const f of ['title','content','category','status'])$(f).oninput=()=>{const e=data.entries.find(e=>e.id===selected);if(!e)return;e[f]=$(f).value;if(f==='category')active=e.category;e.updated=new Date().toISOString();$('words').textContent=e.content.length+' 字';save();render()};$('search').oninput=render;
$('delete').onclick=()=>{if(!confirm('确定删除此设定？无法撤销，请先备份。'))return;data.entries=data.entries.filter(e=>e.id!==selected);save();open(null)};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='万象录备份-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('备份文件已生成，请妥善保存。')};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('备份超过 10 MB');const next=validate(JSON.parse(await file.text()));if(!confirm(`导入 ${next.entries.length} 条设定并替换全部现有内容？请确认已备份。`))return;localStorage.setItem(key,JSON.stringify(next));data=next;blocked=false;active='天地';$('search').value='';$('heading').textContent=active;open(null);notice('导入成功，已保存。')}catch(e){notice('导入失败：'+e.message+'。现有内容未替换。')}finally{$('file').value=''}};open(null);
